import { Component, EventEmitter, Input, Output } from '@angular/core';
import { CreditoService } from '../../../controllers/credito.service';
import { Credito, CreditoEstado } from '../../../models/credito.model';
import { FormularioFlotanteComponent } from "../../../shared/formulario-flotante/formulario-flotante.component";

import { FormsModule } from '@angular/forms';

@Component({
    selector: 'app-credito-estado',
    imports: [
    FormsModule,
    FormularioFlotanteComponent
],
    templateUrl: './credito-estado.component.html',
    styleUrl: './credito-estado.component.css'
})
export class CreditoEstadoComponent {
  @Input() show: boolean=false
  @Output() showChange= new EventEmitter<boolean>()
  @Input() accion?:CreditoEstado
  @Input() credito?:Credito

  comentarios:string=''

  constructor(
    public creditoController :CreditoService
  ){}

  title(){
    switch(this.accion){
      case 'ACTIVO':
        return 'Activar'
      case 'RECHAZADO':
        return'Rechazar'
      case 'FINALIZADO':
        return 'Finalizar'
    }
    return 'Cambiar estado de'
  }

  async submit(){
    if(!this.credito) return
    if(this.accion){
      this.credito.estado=this.accion
    }
    const res = await this.creditoController.cambiarEstado(this.credito,this.accion??this.credito.estado, this.comentarios)
    if(res){
      this.show=false
      this.showChange.emit(false)
    }
  }
}
