import { Component } from '@angular/core';
import { AdvancedSearch, Button, FilteredSearch, HeaderButton, RowButton, RowButtonClickEvent, TablaComponent, TableDefinition } from '../../../shared/tabla/tabla.component';
import { CreditoService } from '../../../controllers/credito.service';
import { VerificacionCredito } from '../../../models/verificacion.credito.model';
import { Credito } from '../../../models/credito.model';
import { Router } from '@angular/router';
import { CREDITOS_ESTADOS_BUTTON, CREDITOS_VERIFICAR_BUTTON } from '../creditos.row.buttons';
import { CREDITOS_ADVANCED_SEARCH } from '../creditos.busqueda.avanzada';
import { CREDITOS_FILTERS } from '../creditos.simple.filters';
import { CreditoEstadoComponent } from "../credito-estado/credito-estado.component";
import { UtilsService } from '../../../services/utils.service';
import { CREDITOS_TABLE_HEADERS_BASIC } from '../creditos.table.headers';
import { BuscadorCreditosComponent } from "../../estado-cuenta/shared/buscador-creditos/buscador-creditos.component";
import { Conditional } from '../../../controllers/super.service';

const TABLA_DEF:TableDefinition={
  emptyMsg:'No hay creditos en proceso de validación.',
  columns:[
    {
      key:'id',
      header:'ID',
    },
    {
      key:'verificaciones',
      function: (verificacion: VerificacionCredito[]) =>{
        const autorizadas= verificacion.filter((v)=> v.autorizado_fecha).length
        return autorizadas+' de '+verificacion.length
      },
      header:'Verificaciones',
    },
    ...CREDITOS_TABLE_HEADERS_BASIC,
  ]
}

const EXTRABUTTONS: HeaderButton[]=[
  {
    key:'todos',
    text:'Ver Todos',
    style:{
      button:'btn scale-05 shadow btn-secondary'
    }
  },
  {
    key:'completos',
    text:'Ver Validados',
    style:{
      button:'btn scale-05 shadow btn-success'
    }
  },
  {
    key:'pendientes',
    text:'Ver Pendientes',
    style:{
      button:'btn scale-05 shadow btn-warning'
    }
  }
]

@Component({
    selector: 'app-creditos-en-validacion',
    imports: [
        TablaComponent,
        CreditoEstadoComponent,
        BuscadorCreditosComponent
    ],
    templateUrl: './creditos-en-validacion.component.html',
    styleUrl: './creditos-en-validacion.component.css'
})
export class CreditosEnValidacionComponent {
  tabla= TABLA_DEF
  rowButtons=[CREDITOS_VERIFICAR_BUTTON,CREDITOS_ESTADOS_BUTTON]
  advancedSearch= CREDITOS_ADVANCED_SEARCH
  filters= CREDITOS_FILTERS
  extraButtons=EXTRABUTTONS

  showEstados:boolean=false
  creditoEdit?:Credito

  filtros={filtro:'validacion'}
  conditionals:Conditional[]=[{key:'estado',operator:'=', value:'ACTIVO'}]

  constructor(
    public creditoController: CreditoService,
    private router : Router
  ){}

  onClickEvent(event: RowButtonClickEvent<Credito>){
    if(event.key==='verificar'){
      this.router.navigate(['/main/creditos/validar/'+event.row.id])
    }
    if(event.key='estados'){
      this.creditoEdit=event.row
      this.showEstados=true
    }
  }

  onButtonClick(key:string){
    switch(key){
      case'todos':
        this.filtros={filtro:'validacion'}
        break;
      case'pendientes':
      this.filtros={filtro:'validacion-pendientes'}
      break;
      case'completos':
      this.filtros={filtro:'validacion-completos'}
      break;
    }
  }
}
