import { Component, ViewChild } from '@angular/core';
import { AdvancedSearch, Button, HeaderButton, RowButton, RowButtonClickEvent, TablaComponent, TableDefinition } from '../../../shared/tabla/tabla.component';
import { CreditoService } from '../../../controllers/credito.service';
import { CREDITOS_ADVANCED_SEARCH } from '../creditos.busqueda.avanzada';
import { CREDITOS_FILTERS } from '../creditos.simple.filters';
import { Credito } from '../../../models/credito.model';
import { CreditoEstadoComponent } from "../credito-estado/credito-estado.component";
import { FormularioFlotanteComponent } from "../../../shared/formulario-flotante/formulario-flotante.component";
import { AutocompleteFieldComponent } from "../../../shared/generic-form/autocomplete-field/autocomplete-field.component";
import { CurrencyPipe } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { InversionTipo } from '../../../models/inversion.tipo.model';
import { CREDITOS_TABLE_HEADERS_BASIC } from '../creditos.table.headers';
import { BuscadorCreditosComponent } from "../../estado-cuenta/shared/buscador-creditos/buscador-creditos.component";
import { Conditional } from '../../../controllers/super.service';

const TABLA_DEF: TableDefinition = {
  columns: [
    {
      key: 'id',
      header: 'ID',
    },
    ...CREDITOS_TABLE_HEADERS_BASIC,
  ]
}
const EDITAR_BUTTON: Button = {
  title: 'Ver detalles',
  style: {
    button: 'btn btn-sm btn-info',
    icon: 'bi bi-eye-fill'
  },
}


const DICTAMINACION_BUTTON: RowButton = {
  key: 'dictaminacion',
  style: {
    button: 'btn btn-sm btn-primary',
    icon: 'bi bi-person-raised-hand'
  },
  text: 'Dictaminar'
}
const RECHAZAR_BUTTON: RowButton = {
  key: 'estados',
  style: {
    button: 'btn btn-sm btn-danger',
    icon: 'bi bi-person-x-fill'
  },
  text: 'Rechazar'
}

const EXTRABUTTONS: HeaderButton[] = [
  {
    key: 'todos',
    text: 'Ver Pendientes',
    style: {
      button: 'btn scale-05 shadow btn-secondary'
    }
  },
  {
    key: 'aprobados',
    text: 'Ver Dictaminados',
    style: {
      button: 'btn scale-05 shadow btn-success'
    }
  },
  {
    key: 'rechazados',
    text: 'Ver Rechazados',
    style: {
      button: 'btn scale-05 shadow btn-danger'
    }
  }
]

@Component({
    selector: 'app-creditos-dictaminacion',
    imports: [
    TablaComponent,
    CreditoEstadoComponent,
    FormularioFlotanteComponent,
    AutocompleteFieldComponent,
    FormsModule,
    CurrencyPipe,
    BuscadorCreditosComponent
],
    templateUrl: './creditos-dictaminacion.component.html',
    styleUrl: './creditos-dictaminacion.component.css'
})
export class CreditosDictaminacionComponent {
  tabla = TABLA_DEF
  edit = EDITAR_BUTTON
  rowButtons = [DICTAMINACION_BUTTON, RECHAZAR_BUTTON]
  advancedSearch = CREDITOS_ADVANCED_SEARCH
  filters = CREDITOS_FILTERS
  showAdd: boolean = false

  extraButtons = EXTRABUTTONS

  getExtra: any = { filtro: 'dictaminacion' }
  conditionals: Conditional[]=[]

  showEstados: boolean = false
  creditoEdit?: Credito

  @ViewChild('tablaRef') tablaRef?: TablaComponent<Credito>

  constructor(
    public creditoController: CreditoService
  ) { }

  updateExtraData(extra:any){
    this.getExtra = {
      filtro: this.getExtra.filtro,
      busqueda_avanzada: extra.busqueda_avanzada,
    }
  }

  updateConditionals(cond:Conditional[]){
    this.conditionals=[
      {key:'estado',operator:'=', value:'ACTIVO'},
      ...cond,
    ]
  }

  onRowButtonClick(event: RowButtonClickEvent<Credito>) {
    if (event.key === 'dictaminacion') {
      this.showAdd = true
      this.creditoEdit=event.row
    }
    if (event.key === 'estados') {
      this.creditoEdit = event.row
      this.showEstados = true
    }
  }

  onButtonClick(key: string) {
    if (key == 'todos') {
      this.getExtra = { filtro: 'dictaminacion' }
    }
    if (key === 'aprobados') {
      this.getExtra = { filtro: 'dictaminacion-aprobados' }
    }
    if (key === 'rechazados') {
      this.getExtra = { filtro: 'dictaminacion-rechazados' }
    }
  }

  totalTipo(tipo:InversionTipo):number{
    return (tipo.inversiones_tipos_detalles??[]).reduce((acc,detalle)=>{
      return acc+detalle.monto_solicitado
    },0)??0
  }

  totalInversion():number{
    if(this.creditoEdit?.inversiones_programas?.monto_solicitado) return this.creditoEdit.inversiones_programas.monto_solicitado;
    return (this.creditoEdit?.inversiones_programas?.inversion_tipos??[]).reduce((acc,tipo)=>{
      return acc+this.totalTipo(tipo)
    },0)??0
  }

  async dictaminar(){
    if(!this.creditoEdit) return;
    if(!this.creditoEdit.dictaminado_fecha){
      await this.creditoController.asociarSesion(this.creditoEdit)
      await this.creditoController.autorizarMonto(this.creditoEdit)
    }
    await this.creditoController.dictaminarCredito(this.creditoEdit)
  }

  dictaminadoPor(){
    if(!this.creditoEdit?.dictaminado_por) return''
    if(typeof this.creditoEdit.dictaminado_por == 'number') return ''
    return this.creditoEdit.dictaminado_por.nombre+' '+this.creditoEdit.dictaminado_por.apellido_paterno+' '+this.creditoEdit.dictaminado_por.apellido_materno
  }
}
