import { Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { VerificacionConcepto, VerificacionCredito } from '../../../../models/verificacion.credito.model';
import { VerificacionCreditoService } from '../../../../controllers/verificacion.credito.service';
import { NgClass } from '@angular/common';
import { RouterLink } from '@angular/router';

@Component({
    selector: 'app-simple-verificacion-credito',
    imports: [
    NgClass,
    RouterLink
],
    templateUrl: './simple-verificacion-credito.component.html',
    styleUrl: './simple-verificacion-credito.component.css'
})
export class SimpleVerificacionCreditoComponent {
  @Input() credito_id?:number
  @Input() verificacionCredito?: VerificacionCredito
  @Input() concepto!: VerificacionConcepto
  @Output() verificacionCreditoChange= new EventEmitter<VerificacionCredito>()
  @Input() rowClass?:string='row justify-content-end'
  @Input() divClass?:string='col-12'
  @Input() disabled:boolean=false

  constructor(
    private verificacionCreditoController: VerificacionCreditoService
  ){}

  async ngOnChanges(changes:SimpleChanges){
    if(changes['credito_id'] && this.credito_id){
      this.verificacionCredito= await this.verificacionCreditoController.first({
        credito_id:this.credito_id,
        concepto:this.concepto
      })
      this.verificacionCreditoChange.emit(this.verificacionCredito)
    }
  }

  async swithAndUpdate(key:string){
    if(!this.verificacionCredito) return
    switch(key){
      case 'datos':
        this.verificacionCredito.revision_datos_ingresados=
          this.verificacionCredito.revision_datos_ingresados=='SI'?'NO':'SI'
        break;
      case 'llamada':
        this.verificacionCredito.llamada_telefonica=
          this.verificacionCredito.llamada_telefonica=='SI'?'NO':'SI'
        break;
      case 'aprobar':
        const success=await this.verificacionCreditoController.aprobar(this.verificacionCredito.id)
        if(success){
          this.verificacionCredito.autorizado_fecha = this.verificacionCredito.autorizado_fecha? null: (new Date).toLocaleDateString()
          this.verificacionCreditoChange.emit(this.verificacionCredito)
        } 
        return
        
    }
    const success= await this.verificacionCreditoController.update(this.verificacionCredito.id,this.verificacionCredito, false)
    if(!success.status){
      this.verificacionCredito= await this.verificacionCreditoController.first({credito_id:this.credito_id})
    }
    this.verificacionCreditoChange.emit(this.verificacionCredito)
  }
}
