import { Component } from '@angular/core';
import { AdvancedSearch, FilteredSearch, RowButton, RowButtonClickEvent, TablaComponent, TableDefinition } from "../../../shared/tabla/tabla.component";
import { ActivatedRoute, Router } from '@angular/router';
import { Button } from '../../../shared/button/button.component';
import { Credito } from '../../../models/credito.model';
import { CreditoService } from '../../../controllers/credito.service';
import { CreditoNuevoComponent } from '../credito-nuevo/credito-nuevo.component';
import { CREDITOS_ADVANCED_SEARCH } from '../creditos.busqueda.avanzada';
import { CREDITOS_FILTERS } from '../creditos.simple.filters';
import { CreditoEstadoComponent } from "../credito-estado/credito-estado.component";
import { CREDITOS_CONTRATOS_BUTTON, CREDITOS_DOCUMENTOS_BUTTON, CREDITOS_ESTADOS_BUTTON, CREDITOS_VERIFICAR_BUTTON } from '../creditos.row.buttons';
import { BuscadorCreditosComponent } from "../../estado-cuenta/shared/buscador-creditos/buscador-creditos.component";
import { Conditional } from '../../../controllers/super.service';
import { UtilsService } from '../../../services/utils.service';

const TABLA_DEF: TableDefinition = {
  columns: [
    {
      key: 'id',
      header: 'ID',
    },
    {
      key: 'row',
      function: (row, utils: UtilsService) => utils.nombreClienteFromCredito(row),
      header: 'Nombre Cliente'
    },
    {
      key:'row',
      function: (row, utils: UtilsService) => utils.nombreComercialFromCredito(row),
      header: 'Nombre Negocio',
    },
    {
      key: 'estado',
      header: 'Estado',
    },
    {
      key: 'productos_financieros',
      subKey: 'alias',
      header: 'P Financiero'
    },
    {
      key: 'sucursales',
      subKey: 'nombre',
      header: 'Sucursal'
    },
    {
      key: 'usuarios',
      subKey: 'nombre',
      header: 'Creado por'
    },
    {
      key: 'created_at',
      header: 'Creado en',
      pipe: 'date'
    },
  ]
}

const AGREGAR_BUTTON: Button = {
  text: 'Nuevo Credito',
  style: {
    icon: "bi bi-plus-circle-fill ms-1",
    button: "btn btn btn-secondary shadow text-bold scale-05",
    div: 'col-auto p-1',
  },
}

@Component({
    selector: 'app-creditos-tabla',
    imports: [
        TablaComponent,
        CreditoNuevoComponent,
        CreditoEstadoComponent,
        BuscadorCreditosComponent
    ],
    templateUrl: './creditos-tabla.component.html',
    styleUrl: './creditos-tabla.component.css'
})
export class CreditosTablaComponent {
  tabla = TABLA_DEF
  showAdd: boolean = false
  agregar = AGREGAR_BUTTON
  rowButtons = [CREDITOS_ESTADOS_BUTTON, CREDITOS_VERIFICAR_BUTTON, CREDITOS_CONTRATOS_BUTTON]
  advancedSearch: AdvancedSearch = CREDITOS_ADVANCED_SEARCH
  filters = CREDITOS_FILTERS

  showEstados: boolean = false
  creditoEdit?: Credito

  getExtra:any = {}
  conditionals: Conditional[] = []

  constructor(
    private router: Router, private route: ActivatedRoute, public controller: CreditoService,
  ) { }

  onRowButtonClickEvent(event: RowButtonClickEvent<Credito>) {
    if (event.key == 'verificar') {
      this.router.navigate(['verificaciones/' + event.row.id], { relativeTo: this.route.parent })
    }
    if (event.key == 'documentos') {
      this.router.navigate(['documentos/' + event.row.id], { relativeTo: this.route.parent })
    }
    if (event.key == 'contratos') {
      this.router.navigate(['contratos/' + event.row.id], { relativeTo: this.route.parent })
    }
    if (event.key === 'estados') {
      this.showEstados = true
      this.creditoEdit = event.row
    }
  }

  onEdit(credito: Credito) {
    console.log(credito)
    switch (credito?.productos_financieros?.regimen_fiscal) {
      case 'PERSONA FISICA CON ACTIVIDAD EMPRESARIAL':
        this.router.navigate(['../editar/' + credito.id + '/pf'], { relativeTo: this.route })
        break;
      case 'PERSONA MORAL':
        this.router.navigate(['../editar/' + credito.id + '/pm'], { relativeTo: this.route })
    }
  }
}
