import { Component } from '@angular/core';
import { Credito } from '../../../models/credito.model';
import { CreditoService } from '../../../controllers/credito.service';
import { UtilsService } from '../../../services/utils.service';
import { ActivatedRoute } from '@angular/router';
import { CurrencyPipe, DatePipe } from '@angular/common';
import { TitlecasePipe } from '../../../pipes/titlecase.pipe';
import { FileInputComponent } from "../../../shared/file-input/file-input.component";

@Component({
    selector: 'app-pagares',
    imports: [
    TitlecasePipe,
    DatePipe,
    FileInputComponent,
    CurrencyPipe
],
    templateUrl: './pagares.component.html',
    styleUrl: './pagares.component.css'
})
export class PagaresComponent {
  credito?:Credito
  pagareKeys=[
    'fecha',
    'pago_fijo',
    'abono_a_capital',
    'interes',
    'iva',
    'documento subido',
    'imprimir',
    'Subir'
  ]

  constructor(
    private creditoController:CreditoService,
    public utils: UtilsService,
    private route: ActivatedRoute,
  ){}

  ngOnInit(){
    this.route.paramMap.subscribe(async (params)=>{
      const id= this.utils.intOrNull(params.get('credito_id'))
      if(id){
        this.credito = await this.creditoController.find(id,[
          'creditosPagos'
        ])
        console.log(this.credito)
      }
    })
  }
}
