import { Component } from '@angular/core';
import { AdvancedSearch, Button, HeaderButton, RowButton, RowButtonClickEvent, TablaComponent, TableDefinition } from '../../../shared/tabla/tabla.component';
import { CreditoService } from '../../../controllers/credito.service';
import { Credito } from '../../../models/credito.model';
import { Router } from '@angular/router';
import { CREDITOS_CONTRATOS_BUTTON, CREDITOS_ESTADOS_BUTTON } from '../creditos.row.buttons';
import { CREDITOS_ADVANCED_SEARCH } from '../creditos.busqueda.avanzada';
import { CREDITOS_FILTERS } from '../creditos.simple.filters';
import { CreditoEstadoComponent } from "../credito-estado/credito-estado.component";
import { CREDITOS_TABLE_HEADERS_BASIC } from '../creditos.table.headers';
import { BuscadorCreditosComponent } from "../../estado-cuenta/shared/buscador-creditos/buscador-creditos.component";
import { Conditional } from '../../../controllers/super.service';

const TABLA_DEF: TableDefinition = {
  columns: [
    {
      key: 'id',
      header: 'ID',
    },
    {
      key: 'formalizado_fecha',
      header: 'Fecha Formalizado',
      pipe: 'date'
    },
    ...CREDITOS_TABLE_HEADERS_BASIC,
  ]
}
const EDITAR_BUTTON: Button = {
  style: {
    button: 'btn btn-sm btn-info',
    icon: 'bi bi-eye-fill'
  },
}

const EXTRABUTTONS: HeaderButton[] = [
  {
    key: 'todos',
    text: 'Ver Pendientes',
    style: {
      button: 'btn scale-05 shadow btn-secondary'
    }
  },
  {
    key: 'aprobados',
    text: 'Ver Formalizados',
    style: {
      button: 'btn scale-05 shadow btn-success'
    }
  },
  {
    key: 'rechazados',
    text: 'Ver Rechazados',
    style: {
      button: 'btn scale-05 shadow btn-danger'
    }
  }
]

@Component({
    selector: 'app-creditos-formalizacion',
    imports: [
        TablaComponent,
        CreditoEstadoComponent,
        BuscadorCreditosComponent
    ],
    templateUrl: './creditos-formalizacion.component.html',
    styleUrl: './creditos-formalizacion.component.css'
})
export class CreditosFormalizacionComponent {
  tabla = TABLA_DEF
  edit = EDITAR_BUTTON
  rowButtons = [CREDITOS_CONTRATOS_BUTTON, CREDITOS_ESTADOS_BUTTON]
  advancedSearch = CREDITOS_ADVANCED_SEARCH
  filters = CREDITOS_FILTERS

  headerButtons = EXTRABUTTONS

  showEstados: boolean = false
  creditoEdit?: Credito

  getExtra: any = { filtro: 'formalizacion' }
  conditionals: Conditional[]=[]


  constructor(
    public creditoController: CreditoService,
    private router: Router,
  ) { }

  updateExtraData(extra: any) {
    this.getExtra = {
      filtro: this.getExtra.filtro,
      busqueda_avanzada: extra.busqueda_avanzada,
    }
  }

  updateConditionals(cond: Conditional[]) {
    this.conditionals = [
      { key: 'estado', operator: '=', value: 'ACTIVO' },
      ...cond,
    ]
  }

  onButtonClick(key: string) {
    if (key == 'todos') {
      this.getExtra = { filtro: 'formalizacion' }
    }
    if (key === 'aprobados') {
      this.getExtra = { filtro: 'formalizacion-aprobados' }
    }
    if (key === 'rechazados') {
      this.getExtra = { filtro: 'formalizacion-rechazados' }
    }
  }


  onRowButtonClick(event: RowButtonClickEvent<Credito>) {
    if (event.key === 'contratos') {
      this.router.navigate(['/main/creditos/contratos/' + event.row.id])
    }
    if (event.key = 'estados') {
      this.creditoEdit = event.row
      this.showEstados = true
    }
  }
}
