import { Component, EventEmitter, Input, Output, SimpleChanges, ViewChild } from '@angular/core';
import { CreditoComprobacionService } from '../../../../controllers/credito.comprobacion.service';
import { CreditoComprobacion } from '../../../../models/credito.comprobaciones.model';
import { FormsModule } from '@angular/forms';
import { FileInputComponent } from "../../../../shared/file-input/file-input.component";
import { VanillaDialogService } from '../../../../services/vanilla-dialog/vanilla-dialog.service';


@Component({
    selector: 'app-credito-comprobacion-form',
    imports: [
        FormsModule,
        FileInputComponent
    ],
    templateUrl: './form.component.html',
    styleUrl: './form.component.css'
})
export class CreditoComprobacionFormComponent {
  @ViewChild('fileInput') fileInput: FileInputComponent | undefined

  @Input() edit!: Partial<CreditoComprobacion>
  @Output() editChange = new EventEmitter<CreditoComprobacion>()

  formExtra: any = {};

  constructor(
    public creditoComprobacionController: CreditoComprobacionService,
    private dialog: VanillaDialogService,
  ) { }

  ngOnChanges(changes: SimpleChanges) {
    if (changes['edit']) {
      this.edit.fecha_comprobacion = this.edit.fecha_comprobacion?.substring(0, 10)
      this.edit.fecha_factura = this.edit.fecha_factura?.substring(0, 10)
    }
  }

  public async submit() {
    if (!this.fileInput?.file) {
      this.dialog.show({
        title: 'Algo salió mal',
        tipo: 'danger',
        body: 'Agrega un documento o evidencia del pago.'
      })
      console.error('FORM INVALIDO')
      return;
    }
    const data = await this.creditoComprobacionController.createOrUpdate(this.edit)
    if (data && data.id) {
      this.edit = data
      this.formExtra.id = data.id
      this.fileInput?.upload()
    }
  }
}
