import { Component } from '@angular/core';
import { Credito } from '../../../models/credito.model';
import { CreditoService } from '../../../controllers/credito.service';
import { ActivatedRoute, } from '@angular/router';
import { UtilsService } from '../../../services/utils.service';
import { ContratoCreditoPFAEService } from '../../../services/documentosLegales/contratos/contrato_credito_pfae.service';
import { ContratoCreditoPMService } from '../../../services/documentosLegales/contratos/contrato_credito_pm.service';
import { PagareService } from '../../../services/documentosLegales/contratos/pagare.service';
import { TablaAmortizacionService } from '../../../services/documentosLegales/contratos/tabla_amortizacion.service';
import { NotificacionCobranzaPFAEService } from '../../../services/documentosLegales/contratos/notificacion_cobranza_pfae.service';
import { ReferenciaBancariaService } from '../../../services/documentosLegales/contratos/referencia_bancaria.service';

import { FileInputComponent } from "../../../shared/file-input/file-input.component";
import { ContratoTipo } from '../../../models/contrato.documento';
import { FormsModule } from '@angular/forms';
import { Sesion } from '../../../models/sesion.model';
import { CotizadorService } from '../../cotizador/cotizador.service';
import { CreditoPagoService } from '../../../controllers/credito.pago.service';
import { Cotizacion } from '../../cotizador/cotizador.component';
import { CreditoPago } from '../../../models/credito.pago.model';
import { LocalStorageService } from '../../../services/localStorage/local-storage.service';

@Component({
    selector: 'app-contratos-credito',
    imports: [
    FormsModule,
    FileInputComponent
],
    templateUrl: './contratos-credito.component.html',
    styleUrl: './contratos-credito.component.css'
})
export class ContratosCreditoComponent {
  credito?: Credito
  pagaresKeys = ['fecha', 'pago_fijo', 'abono_a_capital ', 'interes', 'iva', 'saldo_insoluto', 'saldo_soluto']

  showForze: boolean = false
  nota: string = ''

  forceFormalizacion: boolean = false

  sesionRow = (row: Sesion) => {
    return 'No. ' + row.sesion + ' - ' + row.tipo_sesion
  }

  constructor(
    public creditoController: CreditoService,
    private route: ActivatedRoute,
    public contrato_credito_pfea: ContratoCreditoPFAEService,
    public contrato_credito_pm: ContratoCreditoPMService,
    public pagare: PagareService,
    public tabla_amortizacion: TablaAmortizacionService,
    public notificacion_cobranza: NotificacionCobranzaPFAEService,
    public referencia_bancaria: ReferenciaBancariaService,
    public utils: UtilsService,
    private cotizador: CotizadorService,
    private creditoPagoController: CreditoPagoService,
    private localStorage: LocalStorageService,
  ) { }

  updateAmortizacionDates() {
    if (!this.credito) return
    if (!this.credito.fecha_convenio) return
    this.credito.fecha_amortizacion = this.getFechaPrimerAmorizacion(this.credito.fecha_convenio)
    this.credito.fecha_pagare = this.fechaTentativaPagare(this.credito.fecha_amortizacion)
    this.creditoController.update(this.credito.id, {
      fecha_convenio: this.credito.fecha_convenio,
      fecha_amortizacion: this.credito.fecha_amortizacion,
      fecha_pagare: this.credito.fecha_pagare,
    })
  }

  ngOnInit() {
    this.route.paramMap.subscribe(async (params) => {
      const id = this.utils.intOrNull(params.get('credito_id'))
      if (id) {
        this.credito = await this.creditoController.find(id, [
          "*",
        ])
        //this.setPagos()
        if (this.credito) {
          this.credito.fecha_convenio = this.credito?.fecha_convenio?.substring(0, 10)
          this.credito.fecha_amortizacion = this.credito.fecha_amortizacion?.substring(0, 10)
          this.credito.fecha_pagare = this.credito.fecha_pagare?.substring(0, 10)
        }

        console.log(this.credito)
      }
    })
  }

  public async formalizarCredito() {
    if (!this.credito?.formalizado_fecha) {
      await this.limpiarAmortizaciones()
      const res = await this.crearNuevasAmortizaciones()
      if (!res) return
    }
    await this.creditoController.formalizarCredito(this.credito!)
  }

  private async crearNuevasAmortizaciones() {
    const pagos = this.cotizador.pagosResponseFromCredito(this.credito)
    const amortizaciones: Partial<CreditoPago>[] = (pagos?.lista_pagos ?? []).map(p => ({
      credito_id: this.credito?.id!,
      fecha: p.fecha,
      pago_fijo: p.pago_fijo,
      abono_a_capital: p.abono_a_capital,
      interes: p.interes,
      iva: p.iva,
      documento_url: '',
    }))
    return await this.creditoPagoController.multipleNews(amortizaciones)
  }

  private async limpiarAmortizaciones() {
    if (!this.credito?.creditos_pagos?.length) return
    const toDelete = this.credito.creditos_pagos.map(p => ({
      ...p,
      deleted_at: (new Date()).toISOString().substring(0, 10)
    }))
    return await this.creditoPagoController.multipleUpdate(toDelete)
  }

  urlDoc(document: ContratoTipo) {
    const doc = this.credito?.contratos_documentos?.find((doc) => doc.tipo == document)
    return doc?.documento_url
  }

  async onPagareUpload(url: string) {
    if (!this.credito?.credito_pagares) {
      const credito = await this.creditoController.find(this.credito!.id, ['creditoPagares'])
      this.credito!.credito_pagares = credito?.credito_pagares
    } else {
      this.credito.credito_pagares.documento_url = url
    }
  }

  onUrlChange(document: ContratoTipo, url: string) {
    const doc = this.credito?.contratos_documentos?.find((doc) => doc.tipo == document)
    console.log(this.credito, doc)
    if (doc) {
      doc.documento_url = url
    } else {
      this.credito?.contratos_documentos?.push({
        credito_id: 0,
        usuario_id: 0,
        tipo: document,
        documento_url: url,
        id: 0,
        deleted_at: null,
        created_at: '',
        updated_at: null
      })
    }
  }

  /**
     * Calcula la fecha tentativa de pago de un pagaré, sumando 3 meses a la fecha tentativa de convenio.
     *
     * @param {Date|string} [date=new Date()] - Fecha inicial (puede ser un objeto Date o una cadena de fecha).
     * Si no se proporciona, se utiliza la fecha actual.
     * @returns {Date} - La fecha tentativa de pago del pagaré.
     */
  fechaTentativaPagare(date: Date | string = new Date()): string {
    // Asegura que la entrada sea un objeto Date
    const inputDate = typeof date === 'string' ? new Date(date) : date;

    // Calcula la fecha tentativa del convenio
    const fechaConvenio = new Date(this.getFechaPrimerAmorizacion(inputDate));

    // Calcula la fecha del último día del tercer mes siguiente
    const year = fechaConvenio.getFullYear();
    const month = fechaConvenio.getMonth() + 2;
    const lastDayOfMonth = new Date(year, month, 0);

    return this.utils.shortInputDateString(lastDayOfMonth);
  }

  /**
     * Calcula una fecha tentativa para un convenio basado en la fecha actual o dada.
     *
     * - Si el día actual es menor o igual a 15, la fecha tentativa será el último día del mes actual.
     * - Si el día actual es mayor a 15, la fecha tentativa será el último día del mes siguiente.
     *
     * @returns {Date} - La fecha tentativa calculada.
     */
  getFechaPrimerAmorizacion(date: Date | string = new Date()): string {
    if (typeof date === 'string') {
      date = new Date(date)
    }
    // Obtiene la fecha actual
    const currentDate = date;

    // Extrae el día, mes y año actual
    const currentDay = currentDate.getDate();
    const currentMonth = currentDate.getMonth();
    const currentYear = currentDate.getFullYear();

    let dateNew;

    if (currentDay < 15) {
      // Si el día actual es menor o igual a 15, establece la fecha como el último día del mes actual
      dateNew = new Date(currentYear, currentMonth + 1, 0);
    } else {
      // Si el día actual es mayor a 15, establece la fecha como el último día del mes siguiente
      dateNew = new Date(currentYear, currentMonth + 2, 0);
    }

    // Retorna la fecha tentativa calculada
    return this.utils.shortInputDateString(dateNew);
  }
}
