import { Component } from '@angular/core';
import { AdvancedSearch, Button, HeaderButton, RowButton, RowButtonClickEvent, TablaComponent, TableDefinition } from '../../../shared/tabla/tabla.component';
import { CreditoService } from '../../../controllers/credito.service';
import { Credito } from '../../../models/credito.model';
import {  CREDITOS_ESTADOS_BUTTON, CREDITOS_LIBERACION_BUTTON } from '../creditos.row.buttons';
import { CREDITOS_ADVANCED_SEARCH } from '../creditos.busqueda.avanzada';
import { CREDITOS_FILTERS } from '../creditos.simple.filters';
import { CreditoEstadoComponent } from "../credito-estado/credito-estado.component";
import { FormularioFlotanteComponent } from "../../../shared/formulario-flotante/formulario-flotante.component";
import { CurrencyPipe, DatePipe } from '@angular/common';
import { UtilsService } from '../../../services/utils.service';
import { SelectFieldComponent } from "../../../shared/generic-form/select-field/select-field.component";
import { SimpleFieldComponent } from "../../../shared/generic-form/simple-field/simple-field.component";
import { CREDITOS_TABLE_HEADERS_BASIC } from '../creditos.table.headers';
import { BuscadorCreditosComponent } from "../../estado-cuenta/shared/buscador-creditos/buscador-creditos.component";
import { Conditional } from '../../../controllers/super.service';

const TABLA_DEF:TableDefinition={
  columns:[
    {
      key:'id',
      header:'ID',
    },
    {
      key:'liberado_fecha',
      header:'Fecha Liberado',
      pipe:'date'
    },
    ...CREDITOS_TABLE_HEADERS_BASIC,
  ]
}
const EDITAR_BUTTON:Button={
  style:{
    button:'btn btn-sm btn-info',
    icon:'bi bi-eye-fill'
  },
}

const EXTRABUTTONS: HeaderButton[] = [
  {
    key: 'todos',
    text: 'Ver Pendientes',
    style: {
      button: 'btn scale-05 shadow btn-secondary'
    }
  },
  {
    key: 'aprobados',
    text: 'Ver Liberados',
    style: {
      button: 'btn scale-05 shadow btn-success'
    }
  },
  {
    key: 'rechazados',
    text: 'Ver Rechazados',
    style: {
      button: 'btn scale-05 shadow btn-danger'
    }
  }
]

@Component({
    selector: 'app-creditos-formalizacion',
    imports: [
    TablaComponent,
    CreditoEstadoComponent,
    FormularioFlotanteComponent,
    DatePipe,
    CurrencyPipe,
    SelectFieldComponent,
    SimpleFieldComponent,
    BuscadorCreditosComponent
],
    templateUrl: './creditos-liberacion.component.html',
    styleUrl: './creditos-liberacion.component.css'
})
export class CreditosLiberacionComponent {
  tabla = TABLA_DEF
  edit=EDITAR_BUTTON
  rowButtons= [CREDITOS_LIBERACION_BUTTON, CREDITOS_ESTADOS_BUTTON]
  advancedSearch= CREDITOS_ADVANCED_SEARCH
  filters= CREDITOS_FILTERS

  headerButtons=EXTRABUTTONS

  showEstados:boolean=false
  creditoEdit?:Credito

  conditionals: Conditional[]=[]
  getExtra: any = { filtro: 'liberacion' }

  showForm:boolean=false

  extraLiberacion={
    cuenta_liberacion:'NO LIBERADO',
    fecha_deposito:'',
    disposicion:'TRANSFERENCIA INDIVIDUAL',
  }

  constructor(
    public creditoController:CreditoService,
    public utils: UtilsService,
  ){}

  onButtonClick(key: string) {
    if (key == 'todos') {
      this.getExtra = { filtro: 'liberacion' }
    }
    if (key === 'aprobados') {
      this.getExtra = { filtro: 'liberacion-aprobados' }
    }
    if (key === 'rechazados') {
      this.getExtra = { filtro: 'liberacion-rechazados' }
    }
  }


  onRowButtonClick(event:RowButtonClickEvent<Credito>){
    if(event.key==='liberacion'){
      this.showForm=true
      this.creditoEdit=event.row
      this.extraLiberacion.cuenta_liberacion= this.creditoEdit.cuenta_liberacion
      this.extraLiberacion.fecha_deposito= this.creditoEdit.fecha_deposito
      this.extraLiberacion.disposicion= this.creditoEdit.disposicion
      return
    }
    if(event.key='estados'){
      this.creditoEdit=event.row
      this.showEstados=true
    }
  }

  onDocumentUpload(url:string){
    if(!this.creditoEdit) return
    this.creditoEdit.carta_instruccion_url=url
  }
}