import { Pipe, PipeTransform } from '@angular/core';
import { Credito } from '../models/credito.model';

@Pipe({
  name: 'clienteId',
  standalone: true
})
export class ClienteIdPipe implements PipeTransform {

  transform(credito: Credito, ...args: unknown[]): unknown {
    const pf = credito?.datos_persona_fisica?.datos_personales
    const pm = credito?.datos_personas_morales
    if (pf) {
        return pf.id
    }
    if(pf){
      return pm?.cliente_id ?? pm?.id
    }
    
    return null;
  }

}
