import { Routes } from "@angular/router";
import { CreditoFormComponent } from "./credito-form/credito-form.component";
import { CreditosTablaComponent } from "./creditos-tabla/creditos-tabla.component";
import { VerificacionesCreditosComponent } from "./verificaciones-creditos/verificaciones-creditos.component";
import { DocumentosCreditosComponent } from "./documentos-creditos/documentos-creditos.component";
import { CreditosEnProcesoComponent } from "./creditos-en-proceso/creditos-en-proceso.component";
import { CreditosEnValidacionComponent } from "./creditos-en-validacion/creditos-en-validacion.component";
import { CreditosDictaminacionComponent } from "./creditos-dictaminacion/creditos-dictaminacion.component";
import { CreditosFormalizacionComponent } from "./creditos-formalizacion/creditos-formalizacion.component";
import { CreditoValidarComponent } from "./credito-validar/credito-validar.component";
import { ContratosCreditoComponent } from "./contratos-credito/contratos-credito.component";
import { PagaresComponent } from "./pagares/pagares.component";
import { CreditosLiberacionComponent } from "./creditos-liberacion/creditos-liberacion.component";
import { CreditosPreliberacionComponent } from "./creditos-preliberacion/creditos-preliberacion.component";
import { CreditosComprobacionesComponent } from "./comprobaciones/comprobaciones.component";

export const creditosRoutes: Routes = [
    { path: '', redirectTo: 'list', pathMatch: 'full' },
    { path: 'list', component: CreditosTablaComponent },
    {
        path: 'editar/:credito_id',
        component: CreditoFormComponent,
        loadChildren: () => import('./credito-form/credito.form.routes').then(m => m.creditoFormRoutes),
    },
    {
        path: 'verificaciones/:credito_id',
        component: VerificacionesCreditosComponent,
        loadChildren: () => import('./verificaciones-creditos/verificaciones.creditos.routes').then(m => m.verificacionesCreditosRoutes),
    },
    {
        path: 'documentos/:credito_id',
        component: DocumentosCreditosComponent,
        loadChildren: () => import('./documentos-creditos/documentos.creditos.routes').then(m => m.creditosDocumentosRoutes),
    },
    {
        path: 'en-proceso',
        title: 'Creditos En Proceso',
        component: CreditosEnProcesoComponent
    },
    {
        path: 'validacion',
        title: 'Creditos En Validacion',
        component: CreditosEnValidacionComponent
    },
    {
        path: 'validar/:credito_id',
        title: 'Validar Crédito',
        component: CreditoValidarComponent,
    },
    {
        path: 'dictaminacion',
        title: 'Créditos en Dictaminción',
        component: CreditosDictaminacionComponent,
    },
    {
        path: 'formalizacion',
        title: 'Créditos en Formalización',
        component: CreditosFormalizacionComponent
    },
    {
        path: 'preliberacion',
        title: 'Créditos en Pre Liberación',
        component: CreditosPreliberacionComponent,
    },
    {
        path: 'liberacion',
        title: 'Créditos en Liberación',
        component: CreditosLiberacionComponent,
    },
    {
        path: 'contratos/:credito_id',
        title: 'Contratos de Cŕedito',
        component: ContratosCreditoComponent,
    },
    {
        path: 'pagares/:credito_id',
        title: 'Pagares',
        component: PagaresComponent,
    },
    {
        path: 'comprobacion',
        title:'Comprobaciones destino credito',
        component: CreditosComprobacionesComponent,
    },
    {
        path: 'comprobacion/:credito_id',
        title:'Comprobaciones destino credito',
        component: CreditosComprobacionesComponent,
    },
]