import { Component } from '@angular/core';
import { Credito } from '../../../models/credito.model';
import { ActivatedRoute, Router } from '@angular/router';
import { Button } from '../../../shared/button/button.component';
import { TableDefinition, TablaComponent, AdvancedSearch } from '../../../shared/tabla/tabla.component';
import { CreditoService } from '../../../controllers/credito.service';
import { CreditoNuevoComponent } from "../credito-nuevo/credito-nuevo.component";
import { CREDITOS_ADVANCED_SEARCH } from '../creditos.busqueda.avanzada';
import { CREDITOS_FILTERS } from '../creditos.simple.filters';
import { CREDITOS_TABLE_HEADERS_BASIC } from '../creditos.table.headers';
import { BuscadorCreditosComponent } from "../../estado-cuenta/shared/buscador-creditos/buscador-creditos.component";
import { Conditional } from '../../../controllers/super.service';

const TABLA_DEF: TableDefinition = {
  columns: [
    {
      key: 'id',
      header: 'ID',
    },
    ...CREDITOS_TABLE_HEADERS_BASIC,
    {
      key: 'created_at',
      header: 'Creado en',
      pipe: 'date'
    },
  ]
}

const AGREGAR_BUTTON: Button = {
  text: 'Nuevo Credito',
  style: {
    icon: "bi bi-plus-circle-fill ms-1",
    button: "btn btn btn-secondary shadow text-bold scale-05",
    div: 'col-auto p-1',
  },
}

@Component({
    selector: 'app-creditos-en-proceso',
    imports: [TablaComponent, CreditoNuevoComponent, BuscadorCreditosComponent],
    templateUrl: './creditos-en-proceso.component.html',
    styleUrl: './creditos-en-proceso.component.css'
})
export class CreditosEnProcesoComponent {
  tabla = TABLA_DEF
  showAdd: boolean = false
  advancedSearch = CREDITOS_ADVANCED_SEARCH
  filters = CREDITOS_FILTERS
  getExtra = {filtro:'en-proceso'}
  conditionals: Conditional[] = [{key:'estado',operator:'=', value:'ACTIVO'}, { key:'deleted_at', operator:'IS NULL', value:null}]
  constructor(
    public creditoController: CreditoService,
    private router: Router,
    private route: ActivatedRoute
  ) { }

  onEdit(credito: Credito) {
    console.log(credito)
    switch (credito?.productos_financieros?.regimen_fiscal) {
      case 'PERSONA FISICA CON ACTIVIDAD EMPRESARIAL':
        this.router.navigate(['../editar/' + credito.id + '/pf'], { relativeTo: this.route })
        break;
      case 'PERSONA MORAL':
        this.router.navigate(['../editar/' + credito.id + '/pm'], { relativeTo: this.route })
    }
  }
}
