import { Component } from '@angular/core';
import { BuscadorCreditosComponent } from '../../estado-cuenta/shared/buscador-creditos/buscador-creditos.component';
import { Credito } from '../../../models/credito.model';
import { CurrencyPipe, DatePipe } from '@angular/common';
import { UtilsService } from '../../../services/utils.service';
import { CreditoComprobacionService } from '../../../controllers/credito.comprobacion.service';
import { ClienteIdPipe } from '../../../pipes/cliente-id.pipe';
import { CreditoComprobacion } from '../../../models/credito.comprobaciones.model';
import { FormularioFlotanteComponent } from '../../../shared/formulario-flotante/formulario-flotante.component';
import { CreditoComprobacionFormComponent } from './form/form.component';
import { ActivatedRoute, Router } from '@angular/router';
import { CreditoService } from '../../../controllers/credito.service';
import { LocalStorageService } from '../../../services/localStorage/local-storage.service';
import { UsuarioLogin } from '../../../auth/auth.model';
import { Permiso } from '../../../models/permiso.model';

@Component({
  selector: 'app-comprobaciones',
  imports: [
    BuscadorCreditosComponent,
    CurrencyPipe,
    DatePipe,
    ClienteIdPipe,
    FormularioFlotanteComponent,
    CreditoComprobacionFormComponent,
  ],
  templateUrl: './comprobaciones.component.html',
  styleUrl: './comprobaciones.component.css',
})
export class CreditosComprobacionesComponent {
  credito?: Credito;
  relations: string[] = [
    'datosPersonaFisica.datosPersonales',
    'datosPersonasMorales',
    'creditoComprobaciones',
  ];

  showForm: boolean = false;
  edit?: Partial<CreditoComprobacion> = {
    credito_id: 0,
    usuario_id: 0,
    monto: 0,
    fecha_comprobacion: null,
    id: 0,
  };
  permisos?: Permiso[] = [];

  constructor(
    public utils: UtilsService,
    private creditoController: CreditoService,
    public creditoComprobacionController: CreditoComprobacionService,
    private router: Router,
    private route: ActivatedRoute,
    private storage: LocalStorageService,
  ) {}

  ngOnInit() {
    this.route.params.subscribe(async (params) => {
      if (params['credito_id']) {
        this.credito = await this.creditoController.find(
          params['credito_id'],
          this.relations,
        );
      }
    });

    this.permisos = (this.storage.getPerfil().permisos_usuarios ?? []).filter(pu => pu.permisos !== undefined).map(pu => pu.permisos!)
    console.log('Permisos:', this.permisos);
  }

  public onCreditoSelected(id: number) {
    this.router.navigate(['/main/creditos/comprobacion', id]);
  }

  public totalComprobaciones(): number {
    return (this.credito?.credito_comprobaciones ?? []).reduce(
      (acc, item) => acc + +item.monto,
      0,
    );
  }

  public esCreditoComprobado(): boolean {
    if (!this.credito?.monto_autorizado) return true;
    if (this.totalComprobaciones() >= this.credito.monto_autorizado) {
      return true;
    }
    return false;
  }

  public editarComprobacion(comp: CreditoComprobacion) {
    this.edit = comp;
    this.showForm = true;
  }

  public nuevaComprobacion() {
    this.edit = {
      credito_id: this.credito!.id,
      usuario_id: 0,
      monto: 0,
      fecha_comprobacion: null,
      id: 0,
    };
    this.showForm = true;
  }

  verificarPermiso(accion: string): boolean {
    switch (accion) {
      case 'edit':
      case 'delete':
      case 'create':
        if (this.permisos) {
          return this.permisos.some(
            (permiso) => permiso.nombre === 'ENCARGADO COBRANZA',
          );
        }
        return false;

      default:
        return false;
    }
  }
}
